-- STEP13 / QA-30: read-only validation of every current registered element.
-- Run as authorized DB administrator; no Auth identities, data writes or schema changes.
-- Expected at 2026-11-26: 170 groups, 663 registered entries, 4148/4148 checks.
with def as (select pg_get_functiondef('ff_private.a07_valid_elements(jsonb,text)'::regprocedure) as s), spec as (select split_part(split_part(s,$q$spec jsonb:='$q$,2),$q$'::jsonb;$q$,1)::jsonb j from def), groups as (select g.key, g.value->>'screen' screen, g.value->'keys' keys from spec cross join lateral jsonb_each(j) g), configs as (select g.key,g.screen,jsonb_agg(jsonb_build_object('key',k.item,'shape','pack','size','normal') order by k.ord) cfg from groups g cross join lateral jsonb_array_elements_text(g.keys) with ordinality k(item,ord) group by g.key,g.screen), checks as (select key,screen,'valid_full' scenario,ff_private.a07_valid_elements(jsonb_build_object(key,cfg),screen) ok from configs union all select key,screen,'remove_registered_element',not ff_private.a07_valid_elements(jsonb_build_object(key,cfg-i),screen) from configs cross join lateral generate_series(0,jsonb_array_length(cfg)-1) i union all select key,screen,'forbidden_visibility_property_'||prop,not ff_private.a07_valid_elements(jsonb_build_object(key,jsonb_set(cfg,array[i::text,prop],val,true)),screen) from configs cross join lateral generate_series(0,jsonb_array_length(cfg)-1) i cross join (values ('hidden','true'::jsonb),('visible','false'::jsonb),('display','"none"'::jsonb),('opacity','0'::jsonb),('disabled','true'::jsonb)) m(prop,val)) select scenario,count(*) checks,count(*) filter(where ok) pass,count(*) filter(where not ok) fail from checks group by scenario order by scenario;
